-- MySQL 8.4.0，在空实验 schema 中执行；同名表存在时请换 schema。
CREATE TABLE idx_students (
  id BIGINT PRIMARY KEY,
  age INT NOT NULL,
  name VARCHAR(40) NOT NULL,
  KEY ix_age (age)
) ENGINE=InnoDB;
INSERT INTO idx_students VALUES (1,1,'Ada'),(2,1,'Lin'),(3,2,'Mo');
-- 小表可能自然选择全表扫描；FORCE仅用于观察指定路径。
EXPLAIN SELECT id,age,name FROM idx_students FORCE INDEX(ix_age) WHERE age=1;
SELECT id,age,name FROM idx_students WHERE age=1;
EXPLAIN SELECT id,age FROM idx_students FORCE INDEX(ix_age) WHERE age=1;
SELECT id,age FROM idx_students WHERE age=1;

CREATE TABLE test_table_union_index(
 id BIGINT PRIMARY KEY,merchant_id INT NOT NULL,order_id INT NOT NULL,
 KEY ix_merchant_order(merchant_id,order_id)
) ENGINE=InnoDB;
INSERT INTO test_table_union_index VALUES(1,3,1),(2,3,2),(3,4,3),(4,4,4),(5,5,1),(6,5,2);
SELECT * FROM test_table_union_index WHERE merchant_id=3 AND order_id=2;
-- Expected id=2. All selected columns are present in the secondary index leaf.
